@page "/settings"
@using sv_2e655c840526402d98a4c9d4aeefd5c1.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2 class="sidebar-title">Settings</h2>
        <ul class="nav-tabs">
            @foreach (var section in _sections)
            {
                <li class="nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastType)">
                @_toastMessage
            </div>
        }
    </main>
</div>

@* ───── Profile Section ───── *@
@{
    RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Profile</h3>
            <div class="profile-form">
                <div class="avatar-area">
                    <div class="avatar-preview">
                        <img src="@_profileAvatarUrl" alt="Avatar" />
                    </div>
                    <span class="avatar-url">@_profileAvatarUrl</span>
                </div>

                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="_profileDisplayName" />
                </div>

                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="_profileEmail" />
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </section>
    };
}

@* ───── Notifications Section ───── *@
@{
    RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>

            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @if (_mutedChannels != null)
                {
                    @for (var i = 0; i < _allChannels.Count; i++)
                    {
                        var channel = _allChannels[i];
                        var isMuted = _mutedChannels.Contains(channel);
                        <label class="channel-item">
                            <input type="checkbox" checked="@isMuted"
                                   @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <span>#@channel</span>
                        </label>
                    }
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h3>Security</h3>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group" style="margin-top:1.5rem;">
                <label class="toggle-item">
                    <span>Two-Factor Authentication</span>
                    <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }

            <h4>Active Sessions</h4>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_securitySettings?.Sessions != null)
                    {
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                                <td>
                                    @if (session.Id != "current")
                                    {
                                        <button class="btn btn-danger btn-sm"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>

            @if (_showRevokeConfirm && _sessionToRevoke != null)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_appearanceTheme == theme)"
                                   @onchange="() => _appearanceTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_appearanceFontSize == size)"
                                   @onchange="() => _appearanceFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <div class="preview-area @(_appearanceTheme == "Dark" ? "dark-preview" : "light-preview") @(_compactMode ? "compact" : "")"
                 style="font-size: @GetPreviewFontSize()">
                <h5>Live Preview</h5>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @_appearanceTheme | Font: @_appearanceFontSize | Language: @_appearanceLanguage</p>
                    <button class="btn btn-primary btn-preview">Sample Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string _toastMessage = "";
    private string _toastType = "";

    // Sidebar sections
    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private List<string> _allChannels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = profileTask.Result;
        ApplyProfile(_savedProfile);

        // Notifications
        var notifs = notifsTask.Result;
        _emailNotifications = notifs.EmailNotifications;
        _pushNotifications = notifs.PushNotifications;
        _weeklyDigest = notifs.WeeklyDigest;
        _allChannels = new List<string>(notifs.MutedChannels);
        _mutedChannels = new List<string>(notifs.MutedChannels);

        // Security
        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        // Appearance
        var appearance = appearanceTask.Result;
        _appearanceTheme = appearance.Theme;
        _appearanceFontSize = appearance.FontSize;
        _appearanceLanguage = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ───── Profile Actions ─────
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ───── Notifications Actions ─────
    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!", "success");
    }

    // ───── Security Actions ─────
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!", "success");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.", "success");
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // ───── Appearance Actions ─────
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!", "success");
    }

    private string GetPreviewFontSize() => _appearanceFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    // ───── Toast ─────
    private async Task ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();
        await Task.Delay(3000);
        _toastMessage = "";
        StateHasChanged();
    }
}

